<script setup lang="ts">
import {computed,ref} from 'vue';
import type {McpServer,McpTarget} from '../api/mcp';
import {splitMcpCommand,joinMcpCommand} from '../utils/mcpCommand';
import McpCheckStatus from './McpCheckStatus.vue';
const props=defineProps<{server?:McpServer;direct?:boolean;lockName?:boolean;busy:boolean;error:string;targets:McpTarget[];initialAgents:string[]}>();
const emit=defineEmits<{close:[];remove:[];save:[servers:McpServer[],assign:boolean,agents:string[],autoCheck:boolean]}>();
const name=ref(props.server?.name||'');const config=ref<Record<string,unknown>>({...props.server?.config});
const mode=ref<'form'|'json'>('form');const raw=ref(JSON.stringify(props.server?.config||{command:'npx',args:['-y','']},null,2));
const transport=ref(props.server?.config.command?'stdio':props.server?.config.type==='sse'?'sse':props.server?'http':'stdio');
const command=ref(joinMcpCommand(String(config.value.command||'npx'),config.value.args||['-y']));
const url=ref(String(config.value.url||''));const cwd=ref(String(config.value.cwd||''));
const pairs=ref(Object.entries((config.value.env||config.value.headers||{}) as Record<string,string>).map(([key,value])=>({key,value})));
const secrets=ref(false);const localError=ref('');const enableDefinition=ref(false);const autoCheck=ref(true);
const startup=ref<string|number>(props.server?.check_timeout_sec||'');const agents=ref([...props.initialAgents]);
const title=computed(()=>props.server?.name||name.value.trim()||'添加 MCP');
const availableTargets=computed(()=>props.targets.filter(t=>t.installed||props.initialAgents.includes(t.agent_id)));
const multiple=computed(()=>{if(mode.value!=='json')return false;try{return parseRaw().length>1;}catch{return false;}});
function timeout(){const n=String(startup.value).trim()?Number(startup.value):undefined;if(n!==undefined&&(!Number.isInteger(n)||n<1||n>300))throw new Error('启动检测超时应为 1–300 秒');return n;}
function build(){
 const c={...config.value};if(enableDefinition.value){delete c.disabled;if(c.enabled===false)c.enabled=true;}
 for(const key of ['command','args','env','cwd','url','headers','type'])delete c[key];c.type=transport.value;
 const entries:Record<string,string>={};for(const p of pairs.value){if(!p.key.trim()){if(p.value)throw new Error('请填写环境变量或请求头名称');continue;}if(p.key in entries)throw new Error('名称重复：'+p.key);entries[p.key]=p.value;}
 if(transport.value==='stdio'){const parts=splitMcpCommand(command.value);if(!parts.length)throw new Error('请填写完整启动命令');c.command=parts[0];c.args=parts.slice(1);if(cwd.value.trim())c.cwd=cwd.value.trim();if(Object.keys(entries).length)c.env=entries;}
 else{c.url=url.value.trim();if(Object.keys(entries).length)c.headers=entries;}
 return c;
}
function parseRaw():McpServer[]{const d=JSON.parse(raw.value);if(!d||typeof d!=='object'||Array.isArray(d))throw new Error('请输入 JSON 对象');const map=d.mcpServers||d.servers||d.mcp_servers;if(map){if(typeof map!=='object'||Array.isArray(map))throw new Error('服务列表必须为对象');return Object.entries(map).map(([name,config])=>({name,config:config as Record<string,unknown>}));}return[{name:name.value.trim(),config:d}];}
function hydrate(s:McpServer){name.value=s.name;config.value=s.config;transport.value=s.config.command?'stdio':s.config.type==='sse'?'sse':'http';command.value=joinMcpCommand(String(s.config.command||'npx'),s.config.args||[]);url.value=String(s.config.url||'');cwd.value=String(s.config.cwd||'');pairs.value=Object.entries((s.config.env||s.config.headers||{}) as Record<string,string>).map(([key,value])=>({key,value}));}
function switchMode(next:'form'|'json'){try{if(next===mode.value)return;if(next==='json')raw.value=JSON.stringify(build(),null,2);else{const parsed=parseRaw();if(parsed.length!==1)throw new Error('多服务 JSON 可直接保存到服务库');hydrate(parsed[0]);}mode.value=next;localError.value='';}catch(e){localError.value=String(e instanceof Error?e.message:e);}}
function changeTransport(t:string){if(t!==transport.value){transport.value=t;pairs.value=[];}}
const draft=computed<McpServer|undefined>(()=>{try{const all=mode.value==='json'?parseRaw():[{name:name.value.trim()||'未命名 MCP',config:build()}];if(all.length!==1)return;return{...all[0],check_timeout_sec:timeout()};}catch{return undefined;}});
function toggleAgent(id:string){if(props.direct||multiple.value)return;agents.value=agents.value.includes(id)?agents.value.filter(a=>a!==id):[...agents.value,id];}
function toggleAll(){const ids=availableTargets.value.filter(t=>t.writable&&t.binding&&!t.app_managed).map(t=>t.agent_id);agents.value=ids.every(id=>agents.value.includes(id))?[]:ids;}
async function copy(){try{const servers=mode.value==='json'?parseRaw():[{name:name.value.trim(),config:build()}];await navigator.clipboard.writeText(JSON.stringify({mcpServers:Object.fromEntries(servers.map(s=>[s.name,s.config]))},null,2));localError.value='配置已复制（可能含凭证），请只粘贴到可信的配置位置。';}catch(e){localError.value=String(e instanceof Error?e.message:e);}}
function save(){
 try{localError.value='';const servers=(mode.value==='json'?parseRaw():[{name:name.value.trim(),config:build()}]).map(s=>({...s,check_timeout_sec:timeout()}));if(!servers.length||servers.length>32)throw new Error('一次可导入 1–32 个 MCP');
 if((props.direct||props.lockName)&&(servers.length!==1||servers[0].name!==props.server?.name))throw new Error('编辑时请保留原服务名称；新服务请使用添加入口');
 for(const s of servers){if(!s.name)throw new Error('请填写服务名称');if(!s.config||typeof s.config!=='object'||Array.isArray(s.config))throw new Error('每个服务配置必须是对象');if(!!s.config.command===!!s.config.url)throw new Error(s.name+' 必须填写命令或地址中的一种');}
 emit('save',servers,servers.length===1,[...agents.value],autoCheck.value);
 }catch(e){localError.value=String(e instanceof Error?e.message:e);}
}
</script>
<template>
<div class="mcp-overlay" @click.self="!busy&&emit('close')"><section class="mcp-editor" role="dialog" aria-modal="true" aria-labelledby="editor-title">
 <header><span class="editor-icon">⌘</span><h2 id="editor-title">{{title}}</h2><div class="header-actions"><button class="json-toggle" :class="{active:mode==='json'}" :disabled="busy" @click="switchMode(mode==='form'?'json':'form')">{{mode==='form'?'JSON 导入 / 编辑':'返回表单'}}</button><button class="icon-close" aria-label="关闭编辑器" :disabled="busy" @click="emit('close')">×</button></div></header>
 <div class="editor-body">
  <div class="form-row"><label for="mcp-name">名称</label><div><input id="mcp-name" v-model="name" :disabled="lockName||direct||busy" autofocus placeholder="例如 yuque"/><p class="field-hint">Agent 用这个名字识别服务。编辑原配置时保留名称。</p></div></div>
  <template v-if="mode==='form'">
   <div class="form-row"><label>运行方式</label><div class="transport-picker"><button v-for="t in [{id:'stdio',label:'命令'},{id:'http',label:'HTTP'},{id:'sse',label:'SSE'}]" :key="t.id" :class="{active:transport===t.id}" :disabled="busy" @click="changeTransport(t.id)">{{t.label}}</button></div></div>
   <div v-if="transport==='stdio'" class="form-row"><label for="mcp-command">命令</label><div><input id="mcp-command" v-model="command" :disabled="busy" spellcheck="false" placeholder="cmd /c npx -y yuque-mcp"/><p class="field-hint">命令与参数写在一起；含空格的路径请加引号。</p></div></div>
   <div v-else class="form-row"><label for="mcp-url">服务地址</label><div><input id="mcp-url" v-model="url" :disabled="busy" placeholder="https://mcp.example.com/mcp"/><p class="field-hint">{{transport==='sse'?'填写 SSE 事件流端点。':'填写 MCP 端点，不是服务的网页地址。'}}</p></div></div>
   <div class="form-row"><label>{{transport==='stdio'?'环境变量':'请求头'}}</label><div><div v-for="(p,i) in pairs" :key="i" class="pair-row"><input v-model="p.key" :disabled="busy" :aria-label="'参数 '+(i+1)+' 名称'" :placeholder="transport==='stdio'?'API_KEY':'Authorization'"/><input v-model="p.value" :disabled="busy" :type="secrets?'text':'password'" :aria-label="'参数 '+(i+1)+' 值'" autocomplete="off" placeholder="参数值"/><button class="icon-close" :disabled="busy" aria-label="移除此参数" @click="pairs.splice(i,1)">×</button></div><div class="pair-actions"><button :disabled="busy" @click="pairs.push({key:'',value:''})">＋ 添加</button><button v-if="pairs.length" @click="secrets=!secrets">{{secrets?'隐藏值':'显示值'}}</button></div><p class="field-hint">值默认遮蔽，仅传给此 MCP。检测时可读取本机环境变量引用。</p></div></div>
   <div v-if="transport==='stdio'" class="form-row advanced-row"><span/><details><summary>工作目录（可选）</summary><input v-model="cwd" :disabled="busy" placeholder="D:/你的项目（绝对路径）"/></details></div>
   <div v-if="config.disabled===true||config.enabled===false" class="form-row"><span/><label class="inline-check"><input v-model="enableDefinition" type="checkbox" :disabled="busy"/>原配置已禁用，保存时启用此定义</label></div>
  </template>
  <div v-else class="form-row"><label for="mcp-config">JSON 配置</label><div><textarea id="mcp-config" v-model="raw" :disabled="busy" spellcheck="false" rows="10"/><p class="field-hint">支持单项配置或完整 mcpServers。多项导入先保存到服务库，再分别分配。</p></div></div>
  <div class="form-row"><label for="mcp-timeout">启动超时</label><div><div class="timeout-field"><input id="mcp-timeout" v-model="startup" :disabled="busy" type="number" min="1" max="300" placeholder="30"/><span>秒</span></div><p class="field-hint">本工具等待启动、握手与工具发现的总时间。留空为 30 秒，Agent 自身的超时配置保留。</p></div></div>
  <div class="form-row"><label>Agent</label><div><div class="agent-picker"><button class="agent-all" :disabled="busy||direct||multiple" @click="toggleAll">全部</button><button v-for="t in availableTargets" :key="t.agent_id" class="agent-chip" :class="{selected:agents.includes(t.agent_id)}" :disabled="busy||multiple||direct||!t.writable||!t.binding||t.app_managed" :title="t.blocked_reason||t.guide?.notes" @click="toggleAgent(t.agent_id)"><i>{{t.name.slice(0,1).toUpperCase()}}</i>{{t.name}}</button></div><p class="field-hint">{{direct?'当前正在编辑原 Agent 配置；分配到其他工具可使用主列表的「分配与启用」。':multiple?'多项 JSON 先保存到服务库。':'选中的 Agent 将接收配置；取消已选项会暂停对应服务。也可以不选择，仅保存到服务库。'}}</p></div></div>
  <div class="form-row check-row"><label>可用性</label><div><McpCheckStatus v-if="draft" :server="draft" :expanded="true"/><p v-else class="field-hint">填写完整命令或地址后，可在保存前立即检测。</p><label class="inline-check auto-check"><input v-model="autoCheck" type="checkbox"/>保存后自动检测连接和工具列表</label><p class="field-hint">会启动此 MCP 或连接远程端点，不自动调用业务工具。</p></div></div>
  <p v-if="error||localError" class="editor-error" role="alert">{{localError||error}}</p>
 </div>
 <footer><div class="footer-left"><button v-if="lockName||direct" :disabled="busy" @click="emit('remove')">{{direct?'从此 Agent 移除':'从服务库移除'}}</button><button :disabled="busy" @click="copy()">复制配置…</button></div><button class="btn" :disabled="busy" @click="emit('close')">取消</button><button class="btn primary" :disabled="busy" @click="save()">{{busy?'正在保存…':direct?'预览修改':'保存'}}</button></footer>
</section></div>
</template>
<style scoped>
.mcp-overlay{position:fixed;inset:0;z-index:100;background:rgba(20,22,30,.3);backdrop-filter:blur(5px);display:flex;align-items:center;justify-content:center;padding:24px}.mcp-editor{width:890px;max-width:100%;max-height:91vh;display:flex;flex-direction:column;background:var(--panel);border:1px solid var(--border);border-radius:17px;box-shadow:0 26px 90px #0003;color:var(--text)}header{display:flex;gap:12px;align-items:center;padding:20px 26px;border-bottom:1px solid var(--border)}.editor-icon{display:grid;place-items:center;width:32px;height:32px;background:var(--panel-2);border-radius:9px;color:var(--muted);font-size:22px}h2{font-size:16px;font-weight:600;margin:0;overflow-wrap:anywhere}.header-actions{display:flex;gap:17px;align-items:center;margin-left:auto}.json-toggle{padding:5px 8px;font-size:10px;border:1px solid var(--border);border-radius:6px;color:var(--muted);background:none;cursor:pointer}.json-toggle.active{background:var(--accent-soft);color:var(--accent)}.icon-close{background:none;border:0;padding:0 2px;color:var(--faint);font-size:21px;cursor:pointer}.editor-body{padding:23px 27px 25px;overflow:auto}.form-row{display:grid;grid-template-columns:85px minmax(0,1fr);column-gap:18px;align-items:start;margin-bottom:17px}.form-row>label{font-size:12px;color:var(--muted);text-align:right;padding-top:10px}.form-row>div,.form-row>details{min-width:0}input,textarea{display:block;width:100%;padding:9px 11px;border:1px solid var(--border);border-radius:8px;background:var(--panel);color:var(--text);font-size:12px;line-height:1.4}input:focus,textarea:focus{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-ring);outline:none}textarea,#mcp-command,.pair-row input{font-family:Consolas,'Microsoft YaHei',monospace}textarea{resize:vertical;line-height:1.7}.field-hint{font-size:10px;color:var(--faint);line-height:1.8;margin:6px 0 0}.transport-picker{display:flex;background:var(--panel-2);padding:3px;border-radius:8px;width:max-content}.transport-picker button{padding:6px 14px;border:0;border-radius:6px;background:none;color:var(--muted);font-size:12px;cursor:pointer}.transport-picker button.active{color:var(--text);background:var(--panel);box-shadow:0 1px 4px #0002}.pair-row{display:grid;grid-template-columns:minmax(120px,1fr) minmax(130px,1.2fr) 18px;gap:9px;align-items:center;margin-bottom:8px}.pair-row input{min-width:0;font-size:11px}.pair-actions{display:flex;gap:16px;margin-top:5px}.pair-actions button,.footer-left button{border:0;background:none;color:var(--muted);font-size:11px;padding:3px 0;cursor:pointer}.pair-actions button:hover,.footer-left button:hover{color:var(--text)}.advanced-row{margin-top:-8px;margin-bottom:15px}summary{font-size:10px;color:var(--faint);cursor:pointer}details input{margin-top:9px}.timeout-field{display:flex;align-items:center;gap:9px}.timeout-field input{width:155px}.timeout-field span{font-size:11px;color:var(--faint)}.agent-picker{display:flex;gap:7px;flex-wrap:wrap}.agent-picker button{display:flex;align-items:center;gap:6px;border:1px solid var(--border);border-radius:7px;background:var(--panel);padding:7px 9px;color:var(--muted);font-size:10px;cursor:pointer;line-height:1.2}.agent-chip i{display:grid;place-items:center;font-style:normal;font:10px Georgia,serif;width:16px;height:16px;background:var(--panel-2);border-radius:4px;color:var(--muted)}.agent-chip.selected{background:var(--accent-soft);border-color:var(--accent);color:var(--text)}.agent-chip.selected i{color:var(--accent)}.agent-picker button:disabled{opacity:.42;cursor:not-allowed}.agent-chip.selected:disabled{opacity:.75}.check-row{margin-bottom:0}.check-row :deep(.mcp-check){margin-top:0}.inline-check{display:flex!important;align-items:center;gap:7px;font-size:11px;color:var(--muted)!important;text-align:left!important;padding:0!important}.inline-check input{display:inline-block;width:13px;height:13px;padding:0;accent-color:var(--accent);flex-shrink:0}.auto-check{margin-top:13px}.editor-error{margin:18px 0 0 103px;font-size:11px;color:var(--red);background:var(--red-soft);padding:11px 13px;border-radius:7px;line-height:1.8;overflow-wrap:anywhere}footer{display:flex;align-items:center;justify-content:flex-end;gap:10px;border-top:1px solid var(--border);padding:16px 25px}.footer-left{display:flex;gap:18px;margin-right:auto}button:disabled{cursor:not-allowed;opacity:.5}button:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:720px){.form-row{grid-template-columns:65px minmax(0,1fr);gap:12px}.editor-body{padding:20px}.pair-row{grid-template-columns:minmax(80px,1fr) minmax(90px,1.2fr) 15px}.editor-error{margin-left:77px}.footer-left{gap:12px}.json-toggle{max-width:120px}}
</style>
